import { act, cleanup, render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { createRef, StrictMode } from "react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { Overlay } from "./overlay";

// Class names of a CSS module are generated by Vite, so pin them for the test.
vi.mock("./overlay.module.css", () => ({
	default: { overlay: "overlay-class" },
}));

// A transition whose end the test controls.
const createTransition = () => {
	const { promise, reject, resolve } = Promise.withResolvers<Animation>();

	return {
		cancel: () => reject(new DOMException("", "AbortError")),
		end: () => resolve({} as Animation),
		transition: { finished: promise } as Animation,
	};
};

describe("Overlay", () => {
	const onClose = vi.fn();

	// jsdom doesn't implement showModal and close, so emulate their effect on
	// `open`.
	const showModal = vi.fn(function (this: HTMLDialogElement) {
		this.open = true;
	});

	const close = vi.fn(function (this: HTMLDialogElement) {
		this.open = false;
	});

	// jsdom doesn't implement animations either: no transitions by default.
	const getAnimations = vi.fn((): Animation[] => []);

	beforeEach(() => {
		HTMLDialogElement.prototype.showModal = showModal;
		HTMLDialogElement.prototype.close = close;
		HTMLDialogElement.prototype.getAnimations = getAnimations;
	});

	afterEach(() => {
		// Vitest globals are off, so Testing Library can't register this itself.
		cleanup();
		vi.clearAllMocks();
	});

	// A closing dialog is excluded from the accessibility tree.
	const getDialog = () => screen.getByRole("dialog", { hidden: true });

	const renderOverlay = () =>
		render(
			<Overlay onClose={onClose} ref={createRef()}>
				{({ onRequestClose }) => (
					<>
						<button type="button">content</button>
						<button onClick={onRequestClose} type="button">
							close
						</button>
					</>
				)}
			</Overlay>,
		);

	const clickContent = async (name: string) => {
		const user = userEvent.setup();
		await user.click(screen.getByRole("button", { hidden: true, name }));
	};

	describe("rendering", () => {
		it("renders a dialog with the children", () => {
			renderOverlay();

			expect(getDialog()).toBeInstanceOf(HTMLDialogElement);
			expect(
				screen.getByRole("button", { hidden: true, name: "content" }),
			).toBeDefined();
		});

		it("merges the custom class name with the overlay class", () => {
			render(
				<Overlay className="custom" onClose={onClose} ref={createRef()} />,
			);

			expect(getDialog().className).toBe("overlay-class custom");
		});

		it("forwards the ref to the dialog", () => {
			const ref = createRef<HTMLDialogElement>();
			render(<Overlay onClose={onClose} ref={ref} />);

			expect(ref.current).toBe(getDialog());
		});
	});

	describe("opening", () => {
		it("opens the dialog as modal on mount", () => {
			renderOverlay();

			expect(showModal).toHaveBeenCalledOnce();
		});

		it("does not call showModal again for a dialog that is already open", () => {
			// Strict Mode runs the effect twice.
			render(
				<StrictMode>
					<Overlay onClose={onClose} ref={createRef()} />
				</StrictMode>,
			);

			expect(showModal).toHaveBeenCalledOnce();
		});
	});

	describe("triggers", () => {
		it("disables native closing of the dialog", () => {
			renderOverlay();

			expect(getDialog().getAttribute("closedby")).toBe("none");
		});

		it("closes on a click on the dialog itself", async () => {
			const user = userEvent.setup();
			renderOverlay();

			await user.click(getDialog());

			await vi.waitFor(() => expect(onClose).toHaveBeenCalledOnce());
		});

		it("does not close on a click inside the content", async () => {
			renderOverlay();

			await clickContent("content");

			expect(close).not.toHaveBeenCalled();
			expect(onClose).not.toHaveBeenCalled();
		});

		it("does not close on a press from the content released on the dialog", async () => {
			const user = userEvent.setup();
			renderOverlay();

			await user.pointer([
				{
					keys: "[MouseLeft>]",
					target: screen.getByRole("button", { name: "content" }),
				},
				{ keys: "[/MouseLeft]", target: getDialog() },
			]);

			expect(close).not.toHaveBeenCalled();
		});

		it("does not close on a press from the dialog released on the content", async () => {
			const user = userEvent.setup();
			renderOverlay();

			await user.pointer([
				{ keys: "[MouseLeft>]", target: getDialog() },
				{
					keys: "[/MouseLeft]",
					target: screen.getByRole("button", { name: "content" }),
				},
			]);

			expect(close).not.toHaveBeenCalled();
		});

		it("closes on Escape", async () => {
			const user = userEvent.setup();
			renderOverlay();

			screen.getByRole("button", { name: "content" }).focus();
			await user.keyboard("{Escape}");

			await vi.waitFor(() => expect(onClose).toHaveBeenCalledOnce());
		});

		it("ignores other keys", async () => {
			const user = userEvent.setup();
			renderOverlay();

			screen.getByRole("button", { name: "content" }).focus();
			await user.keyboard("a{Enter}");

			expect(close).not.toHaveBeenCalled();
		});

		it("closes through the callback passed to the children", async () => {
			renderOverlay();

			await clickContent("close");

			await vi.waitFor(() => expect(onClose).toHaveBeenCalledOnce());
		});
	});

	describe("transition", () => {
		it("closes the dialog natively to start the transition", async () => {
			renderOverlay();

			await clickContent("close");

			expect(close).toHaveBeenCalledOnce();
		});

		it("reports the close once the transitions end", async () => {
			const fade = createTransition();
			const move = createTransition();
			getAnimations.mockReturnValue([fade.transition, move.transition]);
			renderOverlay();

			await clickContent("close");
			await act(async () => fade.end());

			expect(onClose).not.toHaveBeenCalled();

			await act(async () => move.end());

			expect(onClose).toHaveBeenCalledOnce();
		});

		it("reports the close when a transition is cancelled", async () => {
			const fade = createTransition();
			getAnimations.mockReturnValue([fade.transition]);
			renderOverlay();

			await clickContent("close");
			await act(async () => fade.cancel());

			expect(onClose).toHaveBeenCalledOnce();
		});

		it("ignores another close while closing", async () => {
			const fade = createTransition();
			getAnimations.mockReturnValue([fade.transition]);
			renderOverlay();

			await clickContent("close");
			await clickContent("close");
			await act(async () => fade.end());

			expect(close).toHaveBeenCalledOnce();
			expect(onClose).toHaveBeenCalledOnce();
		});

		it("does not report a close after the dialog is removed", async () => {
			const fade = createTransition();
			getAnimations.mockReturnValue([fade.transition]);
			const { unmount } = renderOverlay();

			await clickContent("close");
			unmount();
			await act(async () => fade.end());

			expect(onClose).not.toHaveBeenCalled();
		});
	});
});
